function readInitial(){
  let trips=[seedTrip()],activeId=trips[0].id,warning='',canPersist=true; let shared:Trip|null=null;
  if(location.hash.startsWith('#trip='))try{
    const payload=location.hash.slice(6);if(payload.length>180000)throw Error();
    const v=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(payload),c=>c.charCodeAt(0))));
    if(isTrip(v))shared=v;else throw Error();
  }catch{warning='This shared itinerary could not be opened. Your own trips are still here.';}
  try{const raw=localStorage.getItem(STORAGE);if(raw){const v=JSON.parse(raw);if(v.version!==1||!Array.isArray(v.trips)||v.trips.length>100||!v.trips.every(isTrip))throw Error();trips=v.trips;activeId=trips.some((t:Trip)=>t.id===v.activeId)?v.activeId:trips[0]?.id||'';}}
  catch{warning='Saved trips could not be opened. A sample trip is shown.';try{const raw=localStorage.getItem(STORAGE);if(raw){localStorage.setItem(STORAGE+'.recovery',raw);warning+=' The original data has been kept for recovery.';}}catch{canPersist=false;warning+=' Saving is paused to protect your original data.';}}
  return {trips,activeId,warning,shared,canPersist};
}
