function Modal({title,onClose,children,wide=false,className=''}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean;className?:string}){
  const ref=useRef<HTMLDialogElement>(null);const close=useRef(onClose);close.current=onClose;
  useEffect(()=>{const el=ref.current!,previous=document.activeElement as HTMLElement|null;el.showModal();const cancel=(e:Event)=>{e.preventDefault();close.current();};el.addEventListener('cancel',cancel);return()=>{el.removeEventListener('cancel',cancel);el.close();previous?.focus();};},[]);
  return <dialog ref={ref} className={`modal ${wide?'modal-wide':''} ${className}`} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal-inner"><div className="sheet-handle"/><div className="modal-heading"><h2>{title}</h2><button className="icon-button soft" onClick={onClose} aria-label="Close dialog"><X size={19}/></button></div>{children}</div></dialog>;
}
