 const[dragged,setDragged]=useState(''),[shareCopied,setShareCopied]=useState(false);
 const[improveOpen,setImproveOpen]=useState(false),[improveSheet,setImproveSheet]=useState(true),[improvePreview,setImprovePreview]=useState<'current'|'suggested'>('suggested'),[improveLocks,setImproveLocks]=useState<string[]>([]);
 const[appliedRoutes,setAppliedRoutes]=useState<{key:string;legs:Record<string,Journey>;hours:ImproveInput['hours'];expires:number}|null>(null);
