 const[addedTarget,setAddedTarget]=useState<{tripId:string;dayIndex:number;aid:string;name:string}|null>(null);
 const mobile=useMobile(),readOnly=!!shared;const active=shared||trips.find(t=>t.id===activeId)||trips[0];const trip=active||initial.trips[0]||seedTrip();const currentDayIdx=Math.min(dayIdx,trip.days.length-1),day=trip.days[currentDayIdx];
 const placeData=usePlaceData(trip,planningView==='overview'?'all':currentDayIdx,screen==='workspace'),places=placeData.places;
