 for(const [id,info] of Object.entries(visitHours.infoByPlaceId)){if(info&&appliedHours[id]&&info.fetchedAt>appliedHours[id]!.fetchedAt)appliedHours[id]=info;}
 const displayHours=comparison?proposal!.hours:appliedHours;
 const visitChecks=new Map(sc.rows.map(row=>[row.it.aid,checkVisitHours(displayHours[row.it.placeId],{date:tripDayDate(trip.startDate,currentDayIdx),start:Math.max(row.start,row.arrive),end:row.physicalEnd,approx:row.approx})]));
