 useEffect(()=>{document.querySelector('.timeline-scroll')?.scrollTo({top:0});document.querySelector('.day-tab.active')?.scrollIntoView({block:'nearest',inline:'nearest'});},[currentDayIdx,activeId,planningView]);
 useEffect(()=>{if(!pendingReveal.current||dialog||planningView!=='day'||(mobile&&mobileView!=='list'))return;const aid=pendingReveal.current;const frame=requestAnimationFrame(()=>{const element=Array.from(document.querySelectorAll<HTMLElement>('[data-activity-id]')).find(el=>el.dataset.activityId===aid);if(element){element.scrollIntoView({block:'nearest',behavior:'smooth'});element.querySelector<HTMLButtonElement>('.activity-select')?.focus({preventScroll:true});pendingReveal.current=null;}});return()=>cancelAnimationFrame(frame);},[currentDayIdx,selected,dialog,mobileView,mobile,planningView]);
