 useEffect(()=>{const change=()=>{setPreview(null);setDialog(null);if(!location.hash.startsWith('#trip=')){setShared(null);setScreen('dashboard');return;}try{const data=location.hash.slice(6);if(data.length>180000)throw Error();const value=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(data),c=>c.charCodeAt(0))));if(!isTrip(value))throw Error();setShared(value);setScreen('workspace');setDayIdx(0);setSelected(null);setDialog(null);}catch{setToast('This shared itinerary could not be opened.');}};window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change);},[]);
 const notify=(label:string)=>{setToast(label);setAddedTarget(null);};
 function commit(label:string,change:(draft:Trip)=>void){if(readOnly)return;const next=clone(trips),target=next.find(t=>t.id===trip.id);if(!target)return;change(target);setHistory(h=>[...h,clone(trips)].slice(-30));setTrips(next);notify(label);}
